// Remove only data generated by THIS project (.data) and build output (dist).
// Never touches paths outside the project root.
import { rmSync, existsSync } from 'node:fs';
import { join } from 'node:path';

const root = process.cwd();
for (const name of ['.data', 'dist']) {
  const target = join(root, name);
  if (existsSync(target)) {
    rmSync(target, { recursive: true, force: true, maxRetries: 5, retryDelay: 50 });
    console.log(`Removed ${name}/`);
  } else {
    console.log(`${name}/ not present; skipped.`);
  }
}
